#include <bits/stdc++.h>
using namespace std;

const int inf = 10000000;

struct SparseTable {
    vector<int> a;
    vector<vector<int>> st;

    SparseTable(const vector<int>& array) {
        int n = array.size();
        a = array;
        int k = (int)floor(log2(n)) + 1;
        st.assign(n, vector<int>(k));
        for (int i = 0; i < n; i++) {
            st[i][0] = i;
        }
        for (int j = 1; (1 << j) <= n; j++) {
            for (int i = 0; i + (1 << j) - 1 < n; i++) {
                if (a[st[i][j - 1]] < a[st[i + (1 << (j - 1))][j - 1]]) {
                    st[i][j] = st[i][j - 1];
                } else {
                    st[i][j] = st[i + (1 << (j - 1))][j - 1];
                }
            }
        }
    }

    int query(int i, int j) {
        if (i >= (int)a.size()) return inf;
        j = min(j, (int)a.size() - 1);
        int len = j - i + 1;
        int k = (int)floor(log2(len));
        return min(a[st[i][k]], a[st[j - (1 << k) + 1][k]]);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, k;
    cin >> n >> k;
    n *= 2;
    vector<int> l(k + 1), r(k + 1);
    for (int i = 0; i < k; i++) {
        cin >> l[i] >> r[i];
    }
    l[k] = n;

    vector<vector<SparseTable>> seg(2, vector<SparseTable>(2));
    for (int j = 0; j < 2; j++) {
        vector<int> a(n / 2 + 2, inf);
        a[n / 2] = 0;
        seg[1][j] = SparseTable(a);
    }

    int p = 0;
    for (int i = k - 1; i >= 0; i--) {
        for (int j = 0; j < 2; j++) {
            vector<int> a(n / 2 + 2, inf);
            for (int c = 0; c <= l[i] && c < (int)a.size(); c++) {
                int best = seg[1 - p][j].query(c + l[i + 1] - l[i], c + l[i + 1] - l[i]);
                best = min(best, 1 + seg[1 - p][1 - j].query(l[i + 1] - (c + r[i] - l[i]), l[i + 1] - c));
                if (r[i] > l[i]) {
                    best = min(best, 2 + seg[1 - p][j].query(c + l[i + 1] - r[i], c + l[i + 1] - l[i] - 1));
                }
                a[c] = best;
            }
            seg[p][j] = SparseTable(a);
        }
        p ^= 1;
    }
    p ^= 1;
    int ans = min(seg[p][0].query(l[0], l[0]), seg[p][1].query(l[0], l[0]));
    if (ans > 2 * k)
        cout << "Hungry\n";
    else {
        cout << "Full\n" << ans << "\n";
    }
    return 0;
}

